function checkPowersOfThree(n) {
  const powers = [];
  for (let p = 1; p <= n; p *= 3) powers.push(p);
  // Try every subset of the powers that do not exceed n.
  for (let mask = 1; mask < (1 << powers.length); mask++) {
    let total = 0;
    for (let i = 0; i < powers.length; i++) if (mask & (1 << i)) total += powers[i];
    if (total === n) return true;
  }
  return false;
}

generator:
function generate(rand, size) {
  const top = size === 'large' ? 15 : 6;
  const limit = size === 'large' ? 10000000 : 400;
  const roll = rand();
  if (roll < 0.45) {
    // A genuine sum of distinct powers (every one of 3^0..3^14 together is still below 10^7).
    let n = 0;
    for (let x = 0, p = 1; x < top; x++, p *= 3) if (rand() < 0.5) n += p;
    return [n === 0 ? 1 : n];
  }
  if (roll < 0.75) {
    // A near miss: a valid sum with one extra small power added, which may create a digit 2.
    let n = 0;
    for (let x = 0, p = 1; x < top; x++, p *= 3) if (rand() < 0.5) n += p;
    n += 3 ** Math.floor(rand() * 4);
    return [Math.min(n, limit)];
  }
  return [1 + Math.floor(rand() * limit)];
}
